4	import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
5	import "@openzeppelin/contracts/access/AccessControl.sol";
6	
7	/// @notice Fixed-supply whole asset units with on-chain investor eligibility.
8	/// @dev Governed by docs/spec/phase2-requirements.md §2, superseding spec-v1
9	/// where revocation and delegated compliance administration differ.
10	contract AssetToken is ERC20, AccessControl {
11	    bytes32 public constant COMPLIANCE_ROLE = keccak256("COMPLIANCE_ROLE");
12	
13	    address public immutable issuer;
14	    mapping(address => bool) public isWhitelisted;
15	
16	    error InvalidIssuer();
17	    error InvalidInitialSupply();
18	    error InvalidInvestor();
19	    error SenderNotWhitelisted(address sender);
20	    error RecipientNotWhitelisted(address recipient);
21	
22	    event WhitelistUpdated(address indexed investor, bool approved, address indexed operator);
23	
24	    /// @dev Phase 2 §2.1–2.2: assign ownership and roles to issuer_, not deployer.
25	    constructor(
26	        string memory name_,
27	        string memory symbol_,
28	        uint256 initialSupply_,
29	        address issuer_
30	    ) ERC20(name_, symbol_) {
31	        if (issuer_ == address(0)) revert InvalidIssuer();
32	        if (initialSupply_ == 0) revert InvalidInitialSupply();
33	
34	        issuer = issuer_;
35	        _grantRole(DEFAULT_ADMIN_ROLE, issuer_);
36	        _grantRole(COMPLIANCE_ROLE, issuer_);
37	        isWhitelisted[issuer_] = true;
38	        emit WhitelistUpdated(issuer_, true, _msgSender());
39	        _mint(issuer_, initialSupply_);
40	    }
41	
42	    /// @dev Phase 2 §2.1: supply and transfers are expressed in whole units.
43	    function decimals() public pure override returns (uint8) {
44	        return 0;
45	    }
46	
47	    /// @notice Compatibility getter for the Phase 1 whitelist interface (§2.3).
48	    function whitelist(address investor) external view returns (bool) {
49	        return isWhitelisted[investor];
50	    }
51	
52	    /// @notice Phase 2 §2.3: revocation blocks movement without altering balances.
53	    /// @dev Repeating the current status is a no-op; only changes emit an event.
54	    function setWhitelisted(address investor, bool approved) external onlyRole(COMPLIANCE_ROLE) {
55	        if (investor == address(0)) revert InvalidInvestor();
56	        if (isWhitelisted[investor] == approved) return;
57	        isWhitelisted[investor] = approved;
58	        emit WhitelistUpdated(investor, approved, _msgSender());
59	    }
60	
61	    /// @dev Phase 2 §2.4: covers transfer and transferFrom, checking the holder
62	    /// rather than the spender. The zero sender is exempt for the initial mint.
63	    function _update(address from, address to, uint256 value) internal override {
64	        if (from != address(0) && !isWhitelisted[from]) revert SenderNotWhitelisted(from);
65	        if (to != address(0) && !isWhitelisted[to]) revert RecipientNotWhitelisted(to);
66	        super._update(from, to, value);
67	    }
68	}
