2	pragma solidity ^0.8.24;
3	
4	import "./AssetToken.sol";
5	import "./AssetSale.sol";
6	
7	/// @notice Platform registry: authorises issuers and deploys AssetToken + AssetSale pairs.
8	/// @dev Governed by docs/spec/phase3-requirements.md §3.1 and decisions D1–D2,
9	/// superseding spec-v1 §4–5 names (`authoriseIssuer`, `deauthoriseIssuer`, `assets`).
10	contract AssetFactory {
11	    enum AssetType {
12	        RealWorld,
13	        Digital
14	    }
15	
16	    struct Asset {
17	        uint256 assetId;
18	        string name;
19	        string symbol;
20	        string description;
21	        AssetType assetType;
22	        uint256 totalSupply;
23	        address tokenContract;
24	        address saleContract;
25	        address issuerAddress;
26	        uint256 unitPriceWei;
27	    }
28	
29	    address public immutable admin;
30	    mapping(address => bool) public authorisedIssuers;
31	    mapping(address => address) public tokenToSale;
32	    Asset[] private _assets;
33	
34	    error InvalidAdmin();
35	    error NotAdmin();
36	    error InvalidIssuer();
37	    error IssuerAlreadyAuthorised(address issuer);
38	    error IssuerNotAuthorised(address issuer);
39	    error InvalidSupply();
40	    error InvalidPrice();
41	    error AssetNotFound(uint256 assetId);
42	
43	    event IssuerAuthorised(address indexed issuer);
44	    event IssuerRevoked(address indexed issuer);
45	    event AssetCreated(uint256 indexed assetId, address indexed token, address sale, address indexed issuer);
46	
47	    modifier onlyAdmin() {
48	        if (msg.sender != admin) revert NotAdmin();
49	        _;
50	    }
51	
52	    /// @dev spec-v1 §4: platform admin is set in the constructor.
53	    constructor(address admin_) {
54	        if (admin_ == address(0)) revert InvalidAdmin();
55	        admin = admin_;
56	    }
57	
58	    /// @dev Phase 3 §3.1; spec-v1 §5 reverts if already authorised.
59	    function authorizeIssuer(address issuer) external onlyAdmin {
60	        if (issuer == address(0)) revert InvalidIssuer();
61	        if (authorisedIssuers[issuer]) revert IssuerAlreadyAuthorised(issuer);
62	        authorisedIssuers[issuer] = true;
63	        emit IssuerAuthorised(issuer);
64	    }
65	
66	    /// @dev Phase 3 §3.1; spec-v1 §5 note: only blocks future createAsset calls.
67	    /// Contracts this issuer already deployed keep operating.
68	    function revokeIssuer(address issuer) external onlyAdmin {
69	        if (!authorisedIssuers[issuer]) revert IssuerNotAuthorised(issuer);
70	        authorisedIssuers[issuer] = false;
71	        emit IssuerRevoked(issuer);
72	    }
73	
74	    /// @notice Deploys a token (supply minted to the caller) and its sale, then registers both.
75	    /// @dev Phase 3 §3.1, decision D2. The caller still has to whitelist and fund the
76	    /// sale (§3.3); the factory holds no role on the token it deploys.
77	    function createAsset(
78	        string calldata name,
79	        string calldata symbol,
80	        string calldata description,
81	        AssetType assetType,
82	        uint256 totalSupply,
83	        uint256 unitPriceWei
84	    ) external returns (uint256 assetId) {
85	        if (!authorisedIssuers[msg.sender]) revert IssuerNotAuthorised(msg.sender);
86	        if (totalSupply == 0) revert InvalidSupply();
87	        if (unitPriceWei == 0) revert InvalidPrice();
88	
89	        AssetToken token = new AssetToken(name, symbol, totalSupply, msg.sender);
90	        AssetSale sale = new AssetSale(address(token), unitPriceWei, msg.sender);
91	
92	        assetId = _assets.length;
93	        _assets.push(Asset({
94	            assetId: assetId,
95	            name: name,
96	            symbol: symbol,
97	            description: description,
98	            assetType: assetType,
99	            totalSupply: totalSupply,
100	            tokenContract: address(token),
101	            saleContract: address(sale),
102	            issuerAddress: msg.sender,
103	            unitPriceWei: unitPriceWei
104	        }));
105	        tokenToSale[address(token)] = address(sale);
106	
107	        emit AssetCreated(assetId, address(token), address(sale), msg.sender);
108	    }
109	
110	    /// @dev Phase 3 §3.1: asset IDs are sequential from 0.
111	    function getAsset(uint256 assetId) external view returns (Asset memory) {
112	        if (assetId >= _assets.length) revert AssetNotFound(assetId);
113	        return _assets[assetId];
114	    }
115	
116	    /// @dev Phase 3 §3.1.
117	    function getAssetCount() external view returns (uint256) {
118	        return _assets.length;
119	    }
120	}
121

