2	pragma solidity ^0.8.24;
3	
4	import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
5	import "./AssetToken.sol";
6	
7	/// @notice Fixed-price escrow sale for one AssetToken.
8	/// @dev Governed by docs/spec/phase3-requirements.md §3.2–3.4 and decision D3,
9	/// superseding spec-v1 §4–5 names (`buy`, `priceWei`, `token`).
10	contract AssetSale {
11	    using SafeERC20 for AssetToken;
12	
13	    AssetToken public immutable assetToken;
14	    address public immutable issuer;
15	    uint256 public immutable pricePerToken;
16	
17	    /// @dev spec-v1 invariant 8: ETH owed to the issuer, zeroed before the payout call.
18	    uint256 public unclaimedProceeds;
19	    bool public saleClosed;
20	
21	    error InvalidToken();
22	    error InvalidIssuer();
23	    error InvalidPrice();
24	    error NotIssuer();
25	    error InvalidQuantity();
26	    error SaleIsClosed();
27	    error SaleNotClosed();
28	    error InvestorNotWhitelisted(address investor);
29	    error InsufficientInventory(uint256 requested, uint256 available);
30	    error IncorrectPayment(uint256 expected, uint256 received);
31	    error NoProceeds();
32	    error WithdrawalFailed();
33	    error NoUnsoldTokens();
34	
35	    event Allocated(uint256 amount);
36	    event Purchased(address indexed buyer, uint256 quantity, uint256 paid);
37	    event ProceedsWithdrawn(uint256 amount);
38	    event SaleClosed();
39	    event UnsoldTokensRecovered(uint256 amount);
40	
41	    modifier onlyIssuer() {
42	        if (msg.sender != issuer) revert NotIssuer();
43	        _;
44	    }
45	
46	    modifier whenOpen() {
47	        if (saleClosed) revert SaleIsClosed();
48	        _;
49	    }
50	
51	    /// @dev Phase 3 §3.3: price is fixed at asset creation and never changes.
52	    constructor(address assetToken_, uint256 pricePerToken_, address issuer_) {
53	        if (assetToken_ == address(0)) revert InvalidToken();
54	        if (issuer_ == address(0)) revert InvalidIssuer();
55	        if (pricePerToken_ == 0) revert InvalidPrice();
56	        assetToken = AssetToken(assetToken_);
57	        pricePerToken = pricePerToken_;
58	        issuer = issuer_;
59	    }
60	
61	    /// @notice Tokens currently held for sale.
62	    /// @dev spec-v1 §7: the investor dashboard shows available tokens.
63	    function availableTokens() public view returns (uint256) {
64	        return assetToken.balanceOf(address(this));
65	    }
66	
67	    /// @notice Moves inventory from the issuer into the sale. The issuer must
68	    /// first whitelist this contract and approve it for `amount`.
69	    /// @dev Phase 3 §3.3; spec-v1 §5 `allocate`.
70	    function allocate(uint256 amount) external onlyIssuer whenOpen {
71	        if (amount == 0) revert InvalidQuantity();
72	        assetToken.safeTransferFrom(issuer, address(this), amount);
73	        emit Allocated(amount);
74	    }
75	
76	    /// @dev Phase 3 §3.2: exact payment, instant settlement (spec-v1 §4 DvP escrow).
77	    function buyTokens(uint256 quantity) external payable whenOpen {
78	        if (quantity == 0) revert InvalidQuantity();
79	        if (!assetToken.isWhitelisted(msg.sender)) revert InvestorNotWhitelisted(msg.sender);
80	        uint256 available = availableTokens();
81	        if (quantity > available) revert InsufficientInventory(quantity, available);
82	        uint256 cost = quantity * pricePerToken;
83	        if (msg.value != cost) revert IncorrectPayment(cost, msg.value);
84	
85	        unclaimedProceeds += msg.value;
86	        assetToken.safeTransfer(msg.sender, quantity);
87	        emit Purchased(msg.sender, quantity, msg.value);
88	    }
89	
90	    /// @dev Phase 3 §3.4; spec-v1 §4 reentrancy requirement and invariant 8:
91	    /// checks-effects-interactions, so the balance is zero before the ETH send.
92	    function withdrawProceeds() external onlyIssuer {
93	        uint256 amount = unclaimedProceeds;
94	        if (amount == 0) revert NoProceeds();
95	        unclaimedProceeds = 0;
96	        (bool ok, ) = issuer.call{value: amount}("");
97	        if (!ok) revert WithdrawalFailed();
98	        emit ProceedsWithdrawn(amount);
99	    }
100	
101	    /// @dev Phase 3 §3.4, decision D3: closing is irreversible.
102	    function closeSale() external onlyIssuer whenOpen {
103	        saleClosed = true;
104	        emit SaleClosed();
105	    }
106	
107	    /// @dev Phase 3 §3.4, decision D3: returns all unsold inventory to the issuer.
108	    function recoverUnsoldTokens() external onlyIssuer {
109	        if (!saleClosed) revert SaleNotClosed();
110	        uint256 amount = availableTokens();
111	        if (amount == 0) revert NoUnsoldTokens();
112	        assetToken.safeTransfer(issuer, amount);
113	        emit UnsoldTokensRecovered(amount);
114	    }
115	}
116

