4	const { ethers, networkHelpers } = await network.create();
5	
6	const SUPPLY = 10_000n;
7	const PRICE = ethers.parseEther("0.001");
8	const INVENTORY = 5_000n;
9	
10	// spec-v1 §9: index 0 = admin, 1 = issuer, 2 = investor.
11	async function deploySale() {
12	  const [admin, issuer, investor, investor2, unapproved, outsider] = await ethers.getSigners();
13	  const factory = await ethers.deployContract("AssetFactory", [admin.address]);
14	  await factory.authorizeIssuer(issuer.address);
15	  await factory.connect(issuer).createAsset(
16	    "Campus Property Token", "CPT", "Fictional campus real estate fund", 0n, SUPPLY, PRICE,
17	  );
18	  const asset = await factory.getAsset(0n);
19	  const token = await ethers.getContractAt("AssetToken", asset.tokenContract, issuer);
20	  const sale = await ethers.getContractAt("AssetSale", asset.saleContract, issuer);
21	  return { factory, token, sale, admin, issuer, investor, investor2, unapproved, outsider };
22	}
23	
24	// Phase 3 §3.3 lifecycle: whitelist the sale, deposit 5,000 CPT, approve investors.
25	async function fundedSale() {
26	  const state = await deploySale();
27	  const saleAddress = await state.sale.getAddress();
28	  await state.token.setWhitelisted(saleAddress, true);
29	  await state.token.approve(saleAddress, INVENTORY);
30	  await state.sale.allocate(INVENTORY);
31	  await state.token.setWhitelisted(state.investor.address, true);
32	  await state.token.setWhitelisted(state.investor2.address, true);
33	  return state;
34	}
35	
36	async function afterPurchase() {
37	  const state = await fundedSale();
38	  await state.sale.connect(state.investor).buyTokens(100n, { value: 100n * PRICE });
39	  return state;
40	}
