42	// spec-v1 invariant 8: an issuer that is a contract and re-enters on payout.
43	async function contractIssuerSale() {
44	  const [, , investor] = await ethers.getSigners();
45	  const harness = await ethers.deployContract("AssetSaleIssuerHarness");
46	  const harnessAddress = await harness.getAddress();
47	  const token = await ethers.deployContract("AssetToken", ["Campus Property Token", "CPT", SUPPLY, harnessAddress]);
48	  const sale = await ethers.deployContract("AssetSale", [await token.getAddress(), PRICE, harnessAddress]);
49	  const tokenAddress = await token.getAddress();
50	  const saleAddress = await sale.getAddress();
51	  await harness.setSale(saleAddress);
52	  await harness.execute(tokenAddress, token.interface.encodeFunctionData("setWhitelisted", [saleAddress, true]));
53	  await harness.execute(tokenAddress, token.interface.encodeFunctionData("setWhitelisted", [investor.address, true]));
54	  await harness.execute(tokenAddress, token.interface.encodeFunctionData("approve", [saleAddress, 1_000n]));
55	  await harness.execute(saleAddress, sale.interface.encodeFunctionData("allocate", [1_000n]));
56	  await sale.connect(investor).buyTokens(300n, { value: 300n * PRICE });
57	  return { harness, token, sale, investor, withdrawData: sale.interface.encodeFunctionData("withdrawProceeds") };
58	}
59	
60	describe("AssetSale — Phase 3", function () {
61	  describe("deployment", function () {
62	    it("deploys with correct assetToken, pricePerToken, and issuer", async function () {
63	      const { token, sale, issuer } = await networkHelpers.loadFixture(deploySale);
64	      expect(await sale.assetToken()).to.equal(await token.getAddress());
65	      expect(await sale.pricePerToken()).to.equal(PRICE);
66	      expect(await sale.issuer()).to.equal(issuer.address);
67	      expect(await sale.availableTokens()).to.equal(0n);
68	      expect(await sale.unclaimedProceeds()).to.equal(0n);
69	      expect(await sale.saleClosed()).to.equal(false);
70	    });
71	
72	    it("rejects a zero token, zero issuer, or zero price", async function () {
73	      const { token, sale, issuer } = await networkHelpers.loadFixture(deploySale);
74	      const tokenAddress = await token.getAddress();
75	      await expect(ethers.deployContract("AssetSale", [ethers.ZeroAddress, PRICE, issuer.address]))
76	        .to.be.revertedWithCustomError(sale, "InvalidToken");
77	      await expect(ethers.deployContract("AssetSale", [tokenAddress, PRICE, ethers.ZeroAddress]))
78	        .to.be.revertedWithCustomError(sale, "InvalidIssuer");
79	      await expect(ethers.deployContract("AssetSale", [tokenAddress, 0n, issuer.address]))
80	        .to.be.revertedWithCustomError(sale, "InvalidPrice");
81	    });
82	
83	    it("exposes no function to change the price after creation", async function () {
84	      const { sale } = await networkHelpers.loadFixture(deploySale);
85	      const names = sale.interface.fragments.filter((f) => f.type === "function").map((f) => (f as { name: string }).name);
86	      expect(names.filter((n) => /price/i.test(n))).to.deep.equal(["pricePerToken"]);
87	    });
88	  });
