93	      const { token, sale, issuer } = await networkHelpers.loadFixture(deploySale);
94	      const saleAddress = await sale.getAddress();
95	      await token.setWhitelisted(saleAddress, true);
96	      await token.approve(saleAddress, INVENTORY);
