98	      await expect(tx).to.emit(sale, "Allocated").withArgs(INVENTORY);
99	      await expect(tx).to.changeTokenBalances(ethers, token, [issuer, sale], [-INVENTORY, INVENTORY]);
100	      expect(await sale.availableTokens()).to.equal(INVENTORY);
101	      expect(await token.allowance(issuer.address, saleAddress)).to.equal(0n);
102	    });
