104	    it("allocate reverts until the issuer whitelists the sale contract", async function () {
105	      const { token, sale } = await networkHelpers.loadFixture(deploySale);
106	      const saleAddress = await sale.getAddress();
107	      await token.approve(saleAddress, INVENTORY);
108	      await expect(sale.allocate(INVENTORY))
109	        .to.be.revertedWithCustomError(token, "RecipientNotWhitelisted").withArgs(saleAddress);
110	    });
111	
112	    it("allocate without an approval reverts", async function () {
113	      const { token, sale } = await networkHelpers.loadFixture(deploySale);
114	      await token.setWhitelisted(await sale.getAddress(), true);
115	      await expect(sale.allocate(1n)).to.be.revertedWithCustomError(token, "ERC20InsufficientAllowance");
116	    });
