118	    it("non-issuer cannot allocate", async function () {
119	      const { sale, outsider } = await networkHelpers.loadFixture(fundedSale);
120	      await expect(sale.connect(outsider).allocate(1n)).to.be.revertedWithCustomError(sale, "NotIssuer");
121	    });
122	
123	    it("allocate with insufficient issuer balance reverts", async function () {
124	      const { token, sale, issuer } = await networkHelpers.loadFixture(fundedSale);
125	      const remaining = SUPPLY - INVENTORY;
