      expect(await token.balanceOf(unapprovedD.address)).to.equal(0n);
      expect(await token.allowance(investorB.address, investorC.address)).to.equal(30n);
      expect(await token.totalSupply()).to.equal(INITIAL_SUPPLY);
    });

